-- Production core schema verified read-only on 2026-10-17.
-- Schema only; no customer data. Independent of the Worker INSERT under test.
PRAGMA foreign_keys = ON;
CREATE TABLE activity_log (   id INTEGER PRIMARY KEY AUTOINCREMENT,   inquiry_id INTEGER NOT NULL,   activity_type TEXT NOT NULL,   activity_note TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   FOREIGN KEY (inquiry_id) REFERENCES inquiries(id) );

CREATE TABLE compliance_rules (   rule_key TEXT PRIMARY KEY,   rule_value TEXT NOT NULL,   rule_description TEXT,   effective_date TEXT,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );

CREATE TABLE consent_history (   id INTEGER PRIMARY KEY AUTOINCREMENT,    inquiry_id INTEGER NOT NULL,    event_type TEXT NOT NULL,   channel TEXT NOT NULL,   purpose TEXT,    permission_granted INTEGER NOT NULL,    consent_version TEXT,    contact_value TEXT,    source TEXT NOT NULL DEFAULT 'Client Intake Form',    event_note TEXT,    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,    FOREIGN KEY (inquiry_id)     REFERENCES inquiries(id) );

CREATE TABLE email_log (   id INTEGER PRIMARY KEY AUTOINCREMENT,    inquiry_id INTEGER,    email_type TEXT NOT NULL,    recipient TEXT NOT NULL,    subject TEXT NOT NULL,    status TEXT NOT NULL DEFAULT 'Prepared',    provider_message_id TEXT,    failure_reason TEXT,    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,    approved_at TEXT,    sent_at TEXT,    FOREIGN KEY (inquiry_id)     REFERENCES inquiries(id) );

CREATE TABLE inquiries (   id INTEGER PRIMARY KEY AUTOINCREMENT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,    inquiry_type TEXT NOT NULL,   first_name TEXT NOT NULL,   last_name TEXT NOT NULL,   email TEXT,   phone TEXT,   preferred_contact TEXT NOT NULL,    county TEXT NOT NULL,   property_type TEXT NOT NULL,   acreage TEXT,   improvements TEXT,   property_location TEXT,   details TEXT,    status TEXT NOT NULL DEFAULT 'New',   internal_notes TEXT,    referred_to_name TEXT,   referred_to_company TEXT,   referred_to_email TEXT,   referred_to_phone TEXT,   referral_date TEXT,    archived INTEGER NOT NULL DEFAULT 0 , consent_version TEXT, consent_recorded_at TEXT, consent_email TEXT, consent_phone TEXT, inquiry_email_allowed INTEGER NOT NULL DEFAULT 1, marketing_email_opt_in INTEGER NOT NULL DEFAULT 0, live_call_opt_in INTEGER NOT NULL DEFAULT 0, text_opt_in INTEGER NOT NULL DEFAULT 0, do_not_email INTEGER NOT NULL DEFAULT 0, do_not_call INTEGER NOT NULL DEFAULT 0, do_not_text INTEGER NOT NULL DEFAULT 0, contact_authority_basis TEXT, contact_authority_started_at TEXT, phone_contact_expires_at TEXT, next_follow_up_date TEXT, next_follow_up_reason TEXT, follow_up_status TEXT NOT NULL DEFAULT 'None', timeframe TEXT, owner_status TEXT, best_contact_time TEXT, referral_source TEXT, source_page TEXT);

